WITH flattened_attrs AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, payload_json, SHIFTRIGHT(status_code, 2) AS status_code_high, context['version'] AS version FROM app_logs WHERE host = 'h4') SELECT CASE WHEN status_code_high >= 2 THEN 'PREMIUM' ELSE 'STANDARD' END AS status_code_high_tier, COUNT(CASE WHEN level = 'ERROR' THEN 1 END) AS error_count, MIN(log_ts) AS started_at, COUNT(*) AS cnt, COUNT(DISTINCT version) AS distinct_versions, APPROX_PERCENTILE(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles FROM flattened_attrs GROUP BY CASE WHEN status_code_high >= 2 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY distinct_versions ASC NULLS FIRST;
